package cn.mop.persistence;
import org.junit.jupiter.api.Test;
import java.util.*;
import java.nio.charset.StandardCharsets;
import static org.junit.jupiter.api.Assertions.*;
class BackupArchiveMigrationTest {
 @Test void explicitV48RequiresV47AndReadOnlyNeverApplies()throws Exception{BackupArchiveSchemaVerifier.resource();var mode=TestSchemaMigration.requestedMode(new String[]{"--apply-backup-archive-staging"});assertEquals(TestSchemaMigration.Mode.APPLY_BACKUP_ARCHIVE_STAGING,mode);assertTrue(TestSchemaMigration.shouldMigrate(mode,TestSchemaMigration.Plan.BACKUP_RUN_JOURNAL_APPLIED));assertFalse(TestSchemaMigration.shouldMigrate(mode,TestSchemaMigration.Plan.BACKUP_ARCHIVE_STAGING_APPLIED));assertFalse(TestSchemaMigration.shouldMigrate(TestSchemaMigration.Mode.READ_ONLY_CHECK,TestSchemaMigration.Plan.BACKUP_ARCHIVE_STAGING_APPLIED));assertThrows(IllegalStateException.class,()->TestSchemaMigration.shouldMigrate(mode,TestSchemaMigration.Plan.BACKUP_DEVICE_COORDINATION_APPLIED));}
 @Test void exactCatalogRejectsMissingExtraOrAlteredDefinition(){for(var expected:List.of(BackupArchiveSchemaVerifier.SUBMISSION_CONSTRAINTS,BackupArchiveSchemaVerifier.EVENT_CONSTRAINTS)){assertDoesNotThrow(()->BackupArchiveSchemaVerifier.requireDefinitions(expected,expected));var missing=new TreeMap<>(expected);missing.pollFirstEntry();assertThrows(IllegalStateException.class,()->BackupArchiveSchemaVerifier.requireDefinitions(expected,missing));var extra=new TreeMap<>(expected);extra.put("extra","0".repeat(64));assertThrows(IllegalStateException.class,()->BackupArchiveSchemaVerifier.requireDefinitions(expected,extra));var changed=new TreeMap<>(expected);changed.put(changed.firstKey(),"0".repeat(64));assertThrows(IllegalStateException.class,()->BackupArchiveSchemaVerifier.requireDefinitions(expected,changed));}}
 @Test void immutableSourceAndDeferredInitialEventAreMandatory()throws Exception{try(var in=getClass().getResourceAsStream("/db/migration/"+BackupArchiveSchemaVerifier.SCRIPT)){assertNotNull(in);String sql=new String(in.readAllBytes(),StandardCharsets.UTF_8);for(String marker:List.of("current_database()<>'mop_test'","UNIQUE(tenant_id,run_id,attempt_number)","DEFERRABLE INITIALLY DEFERRED","Source and initial stage receipt must commit together","FOR UPDATE","clock_timestamp()","GRANT SELECT,INSERT","CHECK(NOT device_execution_authorized)","CHECK(NOT version_registered)","Original attempt must still be running before new upload"))assertTrue(sql.contains(marker),marker);assertFalse(sql.contains("SECURITY DEFINER"));assertFalse(sql.contains("GRANT UPDATE"));assertFalse(sql.contains("GRANT DELETE"));}}
}
